@prefix dc: <http://purl.org/dc/elements/1.1/> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix foaf: <http://xmlns.com/foaf/0.1/> .
@prefix ns: <http://www.w3.org/2003/06/sw-vocab-status/ns#> .
@prefix ns2: <https://w3id.org/cacao/ontology/> .
@prefix ns3: <http://www.cidoc-crm.org/cidoc-crm/> .
@prefix odrl: <http://www.w3.org/ns/odrl/2/> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix schema: <https://schema.org/> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/FritzBückner> rdf:type schema:Person, E21_Person, E39_Actor, foaf:Person ;
    schema:roleName "Filmmaker" ;
    ns2:fieldOfWork <http://example.org/FilmProduction> .

<http://example.org/WalterKonrad> rdf:type schema:Person, E21_Person, E39_Actor, foaf:Person ;
    schema:roleName "Filmmaker" ;
    ns2:fieldOfWork <http://example.org/FilmProduction> .

<http://example.org/LakeChadRegion> rdf:type E53_Place, schema:Place ;
    schema:description "A significant geographical region in central Africa." .

<http://example.org/BudumaPeople> rdf:type E74_Group ;
    schema:alternateName "Yedina" ;
    schema:description "An ethnic group in the Lake Chad region, known for their papyrus boat building." .

<http://example.org/PapyrusBoatBuilding> rdf:type ns2:CACAO_0000003, ns3:E22_Human-Made_Object ;
    schema:description "Craft technique of building boats from papyrus." .

<http://example.org/IWF> rdf:type foaf:Organization ;
    schema:name "Institut für den Wissenschaftlichen Film, Göttingen" .

<http://example.org/ThorHeyerdahl> rdf:type schema:Person, E21_Person, E39_Actor, foaf:Person .

<http://example.org/RaIExpedition> rdf:type E5_Event ;
    schema:name "Ra I Atlantic crossing attempt" ;
    schema:datePublished "1969"^^xsd:gYear ;
    ns3:P11_had_participant <http://example.org/ThorHeyerdahl> ;
    schema:description "An expedition attempting to cross the Atlantic Ocean from west to east." .

<http://example.org/KanemKingdom> rdf:type ns2:CACAO_0000005, E7_Activity ;
    schema:name "Kingdom of Kanem" ;
    ns3:P4_has_time-span <http://example.org/KanemKingdomHistoryTimeSpan> ;
    schema:description "A large kingdom located on the northeast coast of Lake Chad." .

<http://example.org/KanemKingdomHistoryTimeSpan> rdf:type E52_Time-Span ;
    schema:description "Over thousand years of history, with its center shifting between the 14th and 16th centuries." .

<http://example.org/Borno> rdf:type E53_Place, schema:Place ;
    schema:description "Location on the southwest coast of Lake Chad to which the Kanem kingdom's center shifted." .

<http://example.org/Saharapansion> rdf:type E5_Event ;
    schema:name "Expansion of the Sahara" ;
    schema:datePublished "14th-16th Centuries" ;
    schema:description "A historical event leading to the shift of the Kanem kingdom's center." .

<http://example.org/KanuriPeople> rdf:type E74_Group ;
    schema:description "Contemporary people formed from the fusion of numerous ethnic groups, presumably in the 19th century." .

<http://example.org/MandaraMountains> rdf:type E53_Place, schema:Place ;
    schema:description "Mountain regions south of Lake Chad, serving as ecological niches for some ethnicities." .

<http://example.org/LakeChadIslands> rdf:type E53_Place ;
    schema:description "More than 100 islands in Lake Chad, serving as unconquerable retreat areas." .

<http://example.org/ChadSpeakingEthnicities> rdf:type E74_Group ;
    schema:description "Ethnicities primarily inhabiting the Lake Chad islands, including the Buduma." .

<http://example.org/HeinrichBarth> rdf:type schema:Person, E21_Person, E39_Actor, foaf:Person ;
    schema:description "Traveler whose reports describe the Buduma." .

<http://example.org/GustavNachtigal> rdf:type schema:Person, E21_Person, E39_Actor, foaf:Person ;
    schema:description "Traveler whose reports describe the Buduma." .

<http://example.org/NachtigalReport1881> rdf:type E33_Linguistic_Object, schema:CreativeWork ;
    dcterms:title "Nachtigal 1881:317" ;
    dcterms:creator <http://example.org/GustavNachtigal> ;
    schema:description "Gustav Nachtigal's report recounting Buduma activities." .

<http://example.org/SchoaDatbiggVillageAmbush> rdf:type E5_Event ;
    schema:name "Ambush of Schoa Datbigg village" ;
    schema:datePublished "1870-12"^^xsd:gMonthDay ;
    schema:description "An ambush carried out by Buduma against a village, resulting in killings and enslavement." .

<http://example.org/KonradSoundFilmRecordings> rdf:type ns2:Audio, ns2:Video, E73_Information_Object, schema:MediaObject ;
    dcterms:creator <http://example.org/WalterKonrad> ;
    schema:datePublished "Late 19th Century/Early 20th Century" ;
    schema:description "Sound and film recordings documenting the Buduma." .

<http://example.org/LakeChadEconomicChanges> rdf:type E5_Event ;
    schema:description "Economic integration of Lake Chad islands with surrounding nations for agriculture, trade, and smuggling." .

<http://example.org/NewCommunities> rdf:type E74_Group ;
    schema:description "Communities springing up anew on Lake Chad islands, reflecting social post-colonial situations." .

<http://example.org/HarpPlayersDocumentedByKonrad> rdf:type E39_Actor ;
    schema:description "Harp players documented by Walter Konrad, whose music refers to the historic background reported by Nachtigal." .

<http://example.org/Konrad1966Publication> rdf:type E33_Linguistic_Object, schema:CreativeWork ;
    dcterms:creator <http://example.org/WalterKonrad> ;
    schema:datePublished "1966"^^xsd:gYear ;
    schema:description "A publication by Konrad, likely related to his documentation of harp players." .

<http://example.org/BudumaRobbers> rdf:type E74_Group .

<http://example.org/DeerRaisingAgriculture> rdf:type E7_Activity ;
    schema:description "Deer raising as an agricultural industry in northeast Nigeria." .

<http://example.org/BudumaSinging> rdf:type E28_Conceptual_Object ;
    schema:description "Singing that preserves images of a past and possibly a future." .

<http://example.org/FilmCamera> rdf:type ns2:CACAO_0000025 ;
    schema:description "Instrument used for documentation." .

<http://example.org/FilmProduction> rdf:type ns2:CACAO_0000028 .

<http://example.org/HistoricBackground> rdf:type ns2:CACAO_0000005 .

<http://example.org/PastImagesAndMelodies> rdf:type E28_Conceptual_Object .
